{"code":"import time
from functools import wraps

def retry(max_retries=5, base_delay=100, multiplier=2):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            delay = base_delay
            while attempts < max_retries:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    attempts += 1
                    if attempts < max_retries:
                        time.sleep(delay / 1000)  # Convert ms to seconds
                        delay *= multiplier
                    else:
                        raise e  # Reraise the last exception
        return wrapper
    return decorator

# Example usage of the decorator
@retry(max_retries=5, base_delay=100, multiplier=2)
def test_function():
    print('Trying...')
    raise Exception('Failed')  # Simulate a failure for testing

